mod common;
use common::{shared, BUDGET_MS};
use serde_json::{json, Value};

fn dump(stem: &str, tag: &str, props: &Value, frame: i64, (w, h): (u32, u32), dir: &str) {
    let module = common::module(stem);
    let d = module.meta()["durationInFrames"].as_i64().unwrap();
    let ctx = common::ctx(frame, 30.0, d, w, h);
    let (svg, _) = graphic::svg(&module, frame, props, &ctx, BUDGET_MS).unwrap_or_else(|e| panic!("{}", e.message));
    let stride = w as usize * 4;
    let mut out = vec![0u8; stride * h as usize];
    graphic::rasterize(&shared(), &svg, w, h, &mut out, stride).unwrap();
    let rgb: Vec<u8> = out.chunks_exact(4).flat_map(|p| {
        let under = 255 - p[3] as u32;
        let over = |s: u8, bg: u32| (s as u32 + (bg * under + 127) / 255).min(255) as u8;
        [over(p[2], 0x6e), over(p[1], 0x6e), over(p[0], 0x74)]
    }).collect();
    std::fs::create_dir_all(dir).unwrap();
    let f = std::fs::File::create(format!("{dir}/{stem}-{tag}-{w}x{h}-{frame}.png")).unwrap();
    let mut e = png::Encoder::new(std::io::BufWriter::new(f), w, h);
    e.set_color(png::ColorType::Rgb);
    e.set_depth(png::BitDepth::Eight);
    e.write_header().unwrap().write_image_data(&rgb).unwrap();
}

#[test]
fn dump_long() {
    let dir = std::env::var("DUMP").unwrap();
    let cases: Vec<(&str, &str, Value)> = vec![
        ("chapter-card", "default", json!({})),
        ("chapter-card", "long", json!({"kicker": "SECTION FOUR: ADVANCED COLOUR GRADING", "title": "Setting up your very first multicam edit"})),
        ("donut-chart", "default", json!({})),
        ("donut-chart", "long", json!({"values": "1250, 830, 415, 210, 95, 40", "labels": "Colour grading and finishing, Sound design and mixing, Motion graphics, Rough cut assembly, Exports and delivery, Everything else", "title": "Where the editing time went this quarter"})),
        ("donut-chart", "review", json!({"labels": "Colour grading, Audio, Graphics, Other"})),
    ];
    for (stem, tag, over) in cases {
        let module = common::module(stem);
        let mut props = module.defaults();
        for (k, v) in over.as_object().unwrap() { props[k] = v.clone(); }
        let d = module.meta()["durationInFrames"].as_i64().unwrap();
        for size in [(1920, 1080), (1080, 1920), (1080, 1080)] {
            dump(stem, tag, &props, d / 2, size, &dir);
        }
    }
}
EOF
